81	mod tests {
82	    use super::*;
83	
84	    #[test]
85	    fn config_not_found_displays_path() {
86	        let err = BivvyError::ConfigNotFound {
87	            path: PathBuf::from("/foo/bar.yml"),
88	        };
89	        assert!(err.to_string().contains("/foo/bar.yml"));
90	    }
91	
92	    #[test]
93	    fn config_parse_error_displays_path_and_message() {
94	        let err = BivvyError::ConfigParseError {
95	            path: PathBuf::from("/config.yml"),
96	            message: "invalid syntax".into(),
97	        };
98	        let msg = err.to_string();
99	        assert!(msg.contains("/config.yml"));
100	        assert!(msg.contains("invalid syntax"));
101	    }
102	
103	    #[test]
104	    fn config_validation_error_displays_message() {
105	        let err = BivvyError::ConfigValidationError {
106	            message: "missing required field".into(),
107	        };
108	        assert!(err.to_string().contains("missing required field"));
109	    }
110	
111	    #[test]
112	    fn unknown_template_displays_name() {
113	        let err = BivvyError::UnknownTemplate {
114	            name: "nonexistent".into(),
115	        };
116	        assert!(err.to_string().contains("nonexistent"));
117	    }
118	
119	    #[test]
120	    fn circular_dependency_displays_cycle() {
121	        let err = BivvyError::CircularDependency {
122	            cycle: "a → b → a".into(),
123	        };
124	        assert!(err.to_string().contains("a → b → a"));
125	    }
126	
127	    #[test]
128	    fn step_execution_error_displays_step_and_message() {
129	        let err = BivvyError::StepExecutionError {
130	            step: "install_deps".into(),
131	            message: "npm not found".into(),
132	        };
133	        let msg = err.to_string();
134	        assert!(msg.contains("install_deps"));
135	        assert!(msg.contains("npm not found"));
136	    }
137	
138	    #[test]
139	    fn command_failed_displays_command_and_code() {
140	        let err = BivvyError::CommandFailed {
141	            command: "npm install".into(),
142	            code: Some(1),
143	        };
144	        let msg = err.to_string();
145	        assert!(msg.contains("npm install"));
146	        assert!(msg.contains("1"));
147	    }
148	
149	    #[test]
150	    fn requirement_missing_displays_requirement_and_message() {
151	        let err = BivvyError::RequirementMissing {
152	            requirement: "ruby".into(),
153	            message: "Not found on PATH".into(),
154	        };
155	        let msg = err.to_string();
156	        assert!(msg.contains("ruby"));
157	        assert!(msg.contains("Not found on PATH"));
158	    }
159	
160	    #[test]
161	    fn requirement_check_failed_displays_requirement_and_message() {
162	        let err = BivvyError::RequirementCheckFailed {
163	            requirement: "node".into(),
164	            message: "Install command exited with code 1".into(),
165	        };
166	        let msg = err.to_string();
167	        assert!(msg.contains("node"));
168	        assert!(msg.contains("Install command exited with code 1"));
169	    }
170	
171	    #[test]
172	    fn untrusted_url_displays_url_and_hint() {
173	        let err = BivvyError::UntrustedUrl {
174	            url: "https://example.com/config.yml".into(),
175	        };
176	        let msg = err.to_string();
177	        assert!(msg.contains("https://example.com/config.yml"));
178	        assert!(msg.contains("--trust"));
179	    }
180	
181	    #[test]
182	    fn io_error_converts_from_std() {
183	        let io_err = std::io::Error::new(std::io::ErrorKind::NotFound, "file missing");
184	        let err: BivvyError = io_err.into();
185	        assert!(matches!(err, BivvyError::Io(_)));
186	    }
187	
188	    #[test]
189	    fn result_type_alias_works() {
190	        fn returns_error() -> Result<()> {
191	            Err(BivvyError::ConfigValidationError {
192	                message: "test".into(),
193	            })
194	        }
195	        assert!(returns_error().is_err());
196	    }
