311	    crate::sys::open_in_browser(url).map_err(|e| {
312	        anyhow::anyhow!(
313	            "Failed to open URL. You can open it manually:\n  {}\n\nError: {}",
314	            url,
315	            e
316	        )
317	    })
318	}
