165	/// Known private/internal hostnames that should be blocked for SSRF prevention.
166	const BLOCKED_HOSTS: &[&str] = &["localhost", "127.0.0.1", "0.0.0.0", "[::1]"];
167	
168	/// Known cloud metadata IP addresses.
169	const BLOCKED_IPS: &[&str] = &["169.254.169.254", "100.100.100.200"];
170	
171	/// Extract the host from an HTTP/HTTPS URL.
172	fn extract_host(url: &str) -> Option<String> {
173	    // Strip scheme
174	    let without_scheme = url
175	        .strip_prefix("https://")
176	        .or_else(|| url.strip_prefix("http://"))?;
177	    // Take everything before the first '/' or end
178	    let host_port = without_scheme.split('/').next()?;
179	    // Strip port if present
180	    let host = if host_port.starts_with('[') {
181	        // IPv6: [::1]:8080
182	        host_port.split(']').next().map(|h| format!("{}]", h))
183	    } else {
184	        Some(host_port.split(':').next().unwrap_or(host_port).to_string())
185	    };
186	    host
187	}
188	
189	/// Validate extends configuration.
190	pub fn validate_extends(extends: &[ExtendsConfig]) -> Result<()> {
191	    for ext in extends {
192	        if ext.url.is_empty() {
193	            return Err(anyhow!("Extends URL cannot be empty"));
194	        }
195	        if !ext.url.starts_with("http://") && !ext.url.starts_with("https://") {
196	            return Err(anyhow!("Extends URL must be HTTP/HTTPS: {}", ext.url));
197	        }
198	        // SSRF prevention: block private/internal addresses
199	        if let Some(host) = extract_host(&ext.url) {
200	            let host_lower = host.to_lowercase();
201	            if BLOCKED_HOSTS.iter().any(|&h| host_lower == h) {
202	                return Err(anyhow!(
203	                    "Extends URL must not reference localhost or loopback addresses: {}",
204	                    ext.url
205	                ));
206	            }
207	            if BLOCKED_IPS.iter().any(|&ip| host_lower == ip) {
208	                return Err(anyhow!(
209	                    "Extends URL must not reference internal/metadata IP addresses: {}",
210	                    ext.url
211	                ));
212	            }
213	            // Block 10.x.x.x, 172.16-31.x.x, 192.168.x.x ranges
214	            if let Ok(ip) = host.parse::<std::net::Ipv4Addr>() {
215	                if ip.is_private() || ip.is_loopback() || ip.is_link_local() {
216	                    return Err(anyhow!(
217	                        "Extends URL must not reference private IP addresses: {}",
218	                        ext.url
219	                    ));
220	                }
221	            }
222	        }
223	    }
224	    Ok(())
225	}
