    #[test]
    fn chained_extends() {
        let server = MockServer::start();

        // C is the deepest base
        let c_yaml = r#"
app_name: AppC
steps:
  lint:
    command: eslint .
"#;

        // B extends C
        let b_yaml = format!(
            r#"
extends:
  - url: {}
app_name: AppB
steps:
  test:
    command: jest
"#,
            server.url("/c.yml")
