            then.status(200).body(c_yaml);
        });

        server.mock(|when, then| {
            when.method(GET).path("/b.yml");
            then.status(200).body(b_yaml);
        });

        // A extends B
        let config = BivvyConfig {
            app_name: Some("AppA".to_string()),
